// Generate src/blocks/types.gen.ts from /schema/document.schema.json (itself generated from
// the Pydantic block models). `node scripts/gen-types.mjs --check` exits 1 when the file is stale.
import { readFile, writeFile } from "node:fs/promises";
import { compileFromFile } from "json-schema-to-typescript";

const schemaPath = new URL("../../schema/document.schema.json", import.meta.url);
const outPath = new URL("../src/blocks/types.gen.ts", import.meta.url);

const fresh = await compileFromFile(schemaPath.pathname, {
  bannerComment:
    "// Generated by scripts/gen-types.mjs from schema/document.schema.json. Do not edit.\n" +
    "// Change the Pydantic models in backend/documents/blocks.py and run `make gen`.",
  additionalProperties: false,
  unreachableDefinitions: true,
  ignoreMinAndMaxItems: true,
  style: { singleQuote: false, printWidth: 100 },
});

if (process.argv.includes("--check")) {
  const current = await readFile(outPath, "utf8").catch(() => "");
  if (current !== fresh) {
    console.error("src/blocks/types.gen.ts is stale: run `make gen` and commit the result");
    process.exit(1);
  }
} else {
  await writeFile(outPath, fresh);
}
